var n={en:`The commerce monolith gains discounts and partial refunds. Checkout totals must be frozen after payment and duplicate refund messages must not pay twice.`,ua:`Торговий моноліт отримує знижки й часткові повернення. Сума checkout фіксується після оплати, а повторні повідомлення не можуть повернути гроші двічі.`};var o={en:[`Add Promotions and refund-use-case boundaries.`,`Show validation of order eligibility and Billing provider adapter.`,`Record refund IDs, immutable totals and asynchronous status updates.`],ua:[`Додай межі Promotions і повернень.`,`Покажи перевірку придатності замовлення та адаптер провайдера Billing.`,`Зафіксуй ID повернення, незмінні суми та асинхронні оновлення.`]};var t=[{en:`Refunds use a Billing-controlled provider path.`,ua:`Повернення проходить через Billing.`},{en:`A repeated approved refund has only one financial effect.`,ua:`Повтор схваленого повернення має лише один фінансовий ефект.`}];var i={scenario:n,tasks:o,checks:t};export{t as checks,i as default,n as scenario,o as tasks};